#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

long long countLength(long long left, long long right) {
    return left > right ? 0 : (right - left + 1);
}

long long getRight(long long left, long long count) {
    return left + count - 1;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string dummy;
    cin >> dummy;

    string s;
    cin >> s;

    long long n = (long long)s.length();
    long long upb = n - 1;

    long long res = n;

    for (long long i = 1; i <= upb; i++) {
        long long leftLen = countLength(0, i - 1);
        long long rightLen = countLength(i, upb);
        if (leftLen > rightLen) break;

        long long right = getRight(i, leftLen);
        bool equal = true;
        for (long long a = 0, b = i; a <= i - 1 && b <= right; a++, b++) {
            if (s[a] != s[b]) {
                equal = false;
                break;
            }
        }
        if (equal) {
            long long val = 1 + i + (n - i - leftLen);
            res = min(res, val);
        }
    }

    cout << res << "\n";

    return 0;
}
